    INNER JOIN {$wpdb->term_taxonomy} tt ON tr.term_taxonomy_id = tt.term_taxonomy_id AND tt.taxonomy = 'pa_serie'
    INNER JOIN {$wpdb->terms} t ON tt.term_id = t.term_id AND t.slug = 'homunculus'
    INNER JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = '_stock_status'
    WHERE p.post_type = 'product' AND pm.meta_value = 'instock'
");
