function akb_register_attachment( $filename, $title ) {
    global $wpdb;
    $rel_path = '2026/10/' . $filename;
    $existing = $wpdb->get_var( $wpdb->prepare(
        "SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key = '_wp_attached_file' AND meta_value = %s",
        $rel_path
    ) );
    if ( $existing ) {
        echo "  Adjunto ya existe (ID $existing): $filename\n";
        return (int) $existing;
    }
    $upload_dir = wp_upload_dir();
    $attachment = array(
        'post_mime_type' => 'image/avif',
        'post_title'     => $title,
        'post_content'   => '',
        'post_status'    => 'inherit',
        'guid'           => $upload_dir['baseurl'] . '/' . $rel_path,
    );
    $attach_id = wp_insert_attachment( $attachment, $rel_path );
    if ( ! is_wp_error( $attach_id ) ) {
        update_post_meta( $attach_id, '_wp_attached_file', $rel_path );
        echo "  Creado nuevo adjunto ID $attach_id: $filename\n";
        return (int) $attach_id;
    }
    echo "  ERROR creando adjunto: " . $attach_id->get_error_message() . "\n";
    return 0;
}

